1. //! `derrick upgrade` — reserved binary self-update command.
2. 
3. use crate::commands::UpgradeArgs;
4. use crate::exit_code::CliExitCode;
5. 
6. pub(crate) async fn execute(args: UpgradeArgs) -> Result<CliExitCode, crate::CliError> {
7.     use std::io::Write as _;
8. 
9.     let _ = (args.check, args.force);
10.     std::io::stdout()
11.         .lock()
12.         .write_all(
13.             b"derrick upgrade is not yet available; future releases will use GitHub release assets\n",
14.         )
15.         .map_err(|source| crate::CliError::Io {
16.             path: std::path::PathBuf::from("<stdout>"),
17.             source,
18.         })?;
19.     Ok(CliExitCode::Success)
20. }
21.

